package kz.quizgenerator
import org.junit.Assert.*
import org.junit.Test
import org.junit.Rule
import org.junit.rules.TemporaryFolder
import java.io.File
import org.json.JSONObject
class Session070Test {
 @get:Rule val dir=TemporaryFolder()
 private val q=QuizQuestion("q","Верные числа?",listOf("2","3","4"),0,explanation="Два чётных",additionalCorrectIndices=listOf(2))
 private val quiz=Quiz("00000000-0000-0000-0000-000000000002","Банк",listOf(q,q.copy(id="q2",text="Другой")))
 @Test fun examAlwaysBlocksHintsAndFeedbackRegardlessOfGlobalPreferences() {assertFalse(StudySessionPolicy.hints(true,true));assertFalse(StudySessionPolicy.feedback(true,q));assertTrue(StudySessionPolicy.hints(false,true));assertTrue(StudySessionPolicy.feedback(false,q));assertFalse(StudySessionPolicy.feedback(false,q.copy(evidence=AnswerEvidence.CLOUD_AI)))}
 @Test fun snapshotsPreserveExamTimingMultiSelectionAndBookmarks() {val store=ActiveAttemptStore(File(dir.root,"active.json"));val value=ActiveAttempt(quiz,listOf(0,null),1,"attempt",100,200,3,listOf(setOf(0,2),emptySet()),true,true,true,1000,500,3,setOf("q"));store.save(value);assertEquals(value,ActiveAttemptStore(File(dir.root,"active.json")).load());assertFalse(StudySessionPolicy.hints(store.load()!!.examMode,store.load()!!.hints))}
 @Test fun legacySnapshotMigratesFailClosedAndDoesNotInventDuration() {val file=File(dir.root,"active.json");val store=ActiveAttemptStore(file);store.save(ActiveAttempt(quiz,listOf(0,null),0,"attempt",100,200,3));val r=JSONObject(file.readText());for(key in listOf("examMode","hints","revealAnswers","startedAt","startedElapsed","startedBootCount","bookmarks"))r.remove(key);file.writeText(r.toString());val legacy=store.load()!!;assertTrue(legacy.examMode);assertFalse(legacy.hints);assertEquals(emptySet<String>(),legacy.bookmarks);assertNull(StudySessionPolicy.duration(legacy.startedAt,0,3,3,2000,1000))}
 @Test fun elapsedDurationUsesMonotonicClockAndFallsBackAfterReboot() {assertEquals(3000L,StudySessionPolicy.duration(10000,1000,3,3,5000,4000));assertEquals(1000L,StudySessionPolicy.duration(10000,1000,3,4,11000,100));assertNull(StudySessionPolicy.duration(10000,1000,3,4,9000,100));assertEquals("01:05",StudySessionPolicy.durationLabel(65000));assertEquals("Не измерено",StudySessionPolicy.durationLabel(null))}
 @Test fun bookmarksToggleAndUnknownBookmarkCannotEnterSnapshot() {assertEquals(setOf("q"),StudySessionPolicy.bookmark(emptySet(),"q"));assertTrue(StudySessionPolicy.bookmark(setOf("q"),"q").isEmpty());val file=File(dir.root,"active.json");val store=ActiveAttemptStore(file);store.save(ActiveAttempt(quiz,listOf(0,null),0,"attempt",0,0,3));val r=JSONObject(file.readText()).put("bookmarks",org.json.JSONArray(listOf("foreign")));file.writeText(r.toString());assertThrows(IllegalArgumentException::class.java){store.load()}}
 @Test fun historyAndPreferencesRoundTripWithOldHistoryIntact() {val file=File(dir.root,"study.json");val old=StudyData(attempts=listOf(StudyLogic.complete("old",quiz,listOf(0,null),100)));val store=StudyStore(file);store.save(old);val r=JSONObject(file.readText());r.getJSONObject("settings").remove("examMode");r.getJSONArray("attempts").getJSONObject(0).remove("durationMillis");r.getJSONArray("attempts").getJSONObject(0).remove("examMode");file.writeText(r.toString());assertEquals(old,store.load());val data=old.copy(settings=old.settings.copy(examMode=true),attempts=old.attempts+old.attempts[0].copy(id="new",durationMillis=65000,examMode=true));store.save(data);assertEquals(data,store.load())}
 @Test fun mistakeCardsOnlyUseConfirmedAnswersAndKeepAllMultiKeys() {val bank=quiz.copy(questions=listOf(q,q.copy(id="u",evidence=AnswerEvidence.INFERRED)));val answers=listOf(setOf(0),emptySet<Int>());val cards=StudySessionPolicy.mistakeCards(bank,answers,emptyList());assertEquals(1,cards.size);assertEquals("2\n4",cards[0].back);assertTrue(cards[0].evidence.confirmed);assertTrue(StudySessionPolicy.mistakeCards(bank,answers,cards).isEmpty())}
 @Test fun localBankLimitIsIndependentFromGeminiLimitAndShufflePreservesKeys() {val big=quiz.copy(questions=List(800){q.copy(id="q$it")});val prepared=StudyLogic.prepare(big,StudySettings(limit=500,shuffleOptions=true),42);assertEquals(500,prepared.questions.size);assertTrue(prepared.questions.all {it.correctIndices.map(it.options::get).toSet()==setOf("2","4")})}
 @Test fun difficultCardSessionOnlyUsesRealRatingsAndKeepsSelectedIds() {val hard=kz.quizgenerator.ui.screens.CardRow("h","F","B",rating="hard");val easy=hard.copy(id="e",rating="easy");val selected=kz.quizgenerator.ui.screens.CardSessionRules.difficult(listOf(hard,easy));assertEquals(listOf("h"),selected);assertTrue(kz.quizgenerator.ui.screens.CardSessionRules.difficult(listOf(hard.copy(rating="easy"),easy)).isEmpty());assertEquals(listOf("h"),selected)}

 @Test fun timedSessionDurationStopsAtDeadlineWhenAppResumesLate() {assertEquals(60000L,StudySessionPolicy.duration(10000,1000,3,3,130000,121000,70000,61000));assertEquals(60000L,StudySessionPolicy.duration(10000,1000,3,4,130000,121000,70000,121000))}

}
